  .kpi-card.short { border-top-color: var(--c-short); }
  .kpi-card.long { border-top-color: var(--c-long); }
  .kpi-card.accent { border-top-color: var(--c-accent); }
  .kpi-card.red { border-top-color: var(--c-red); }
  .kpi-card.purple { border-top-color: var(--c-purple); }

  /* Tables */
  .data-table {
    width: 100%;
    border-collapse: collapse;
    font-size: .88rem;
  }
  .data-table th {
    background: var(--c-primary);
    color: #fff;
    padding: 10px 12px;
    text-align: center;
    font-weight: 600;
    font-size: .82rem;
    letter-spacing: .3px;
  }
  .data-table th:first-child { text-align: left; }
  .data-table td {
    padding: 9px 12px;
    border-bottom: 1px solid var(--c-border);
    text-align: center;
  }
  .data-table td:first-child { text-align: left; font-weight: 500; }
  .data-table tbody tr:hover { background: #f0f7ff; }
  .data-table .highlight { background: #fff8e6; font-weight: 600; }
  .data-table .missing { color: var(--c-muted); font-style: italic; }

  /* Chart containers */
  .chart-wrap {
    position: relative;
    width: 100%;
    max-width: 100%;
    margin: 0 auto 20px;
  }
  .chart-wrap.medium { max-height: 400px; }
  .chart-row {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 24px;
  }
  @media (max-width: 768px) { .chart-row { grid-template-columns: 1fr; } }

  /* Misc */
  p { margin-bottom: 12px; }
