  .warning-box {
    background: #fff5f5;
    border-left: 4px solid var(--c-red);
    padding: 14px 18px;
    border-radius: 0 var(--radius) var(--radius) 0;
    margin: 16px 0;
    font-size: .93rem;
  }
  .tag {
    display: inline-block;
    padding: 2px 10px;
    border-radius: 12px;
    font-size: .76rem;
    font-weight: 600;
  }
  .tag-mcq  { background: #bee3f8; color: #2a4365; }
  .tag-short { background: #c6f6d5; color: #22543d; }
  .tag-long  { background: #fefcbf; color: #744210; }

  ul.checklist { list-style: none; padding-left: 0; }
  ul.checklist li { position: relative; padding: 6px 0 6px 28px; }
  ul.checklist li::before {
    content: '✓';
    position: absolute;
