        <tr><td>MS-Access objects</td><td class="h2">3</td><td class="h3">5</td><td class="h2">4</td><td class="h4">6</td><td class="h5">8</td><td class="h0">—</td><td class="h2">4</td><td class="h2">3</td><td class="h2">4</td><td class="h2">4</td><td class="h2">3</td><td><strong>44</strong></td></tr>
